public class Stack<Type> extends ArrayList<Type>
{
    public void insert(Type x)
    {
        add(x);
    }

    public Type extract()
    {
        if (isEmpty())
            throw new RuntimeException("Stack ist leer");
        return remove(size()-1);
    }

    // Alias-Name für insert
    public void push(Type x)
    {
        insert(x);
    }

    // Alias-Name für extract
    public Type pop()
    {
        return extract();
    }

}
